THIS^.proc.power_on._copyToModel_Process( model := model.proc.power_on );
THIS^.proc.power_off._copyToModel_Process( model := model.proc.power_off );

parts.temperatureSensor();
parts.fan();
parts.mount();
parts.pc();
stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := ((parts.fan.stat.health = HealthStatus.good) OR (parts.fan.stat.health = HealthStatus.warning)) AND (((parts.mount.stat.health = HealthStatus.good) OR (parts.mount.stat.health = HealthStatus.warning)) AND (((parts.pc.stat.health = HealthStatus.good) OR (parts.pc.stat.health = HealthStatus.warning)) AND ((parts.temperatureSensor.stat.health = HealthStatus.good) OR (parts.temperatureSensor.stat.health = HealthStatus.warning)))),
    hasWarning := (parts.fan.stat.health = HealthStatus.warning) OR ((parts.mount.stat.health = HealthStatus.warning) OR ((parts.pc.stat.health = HealthStatus.warning) OR (parts.temperatureSensor.stat.health = HealthStatus.warning))));
proc.power_on();
proc.power_off();
proc.reset();

THIS^.parts.temperatureSensor._copyFromModel_TemperatureMeasurement( model := model.parts.temperatureSensor );
THIS^.parts.fan._copyFromModel_solarFan( model := model.parts.fan );
